        if (dp[left][right] != -1) {
            return dp[left][right];
        }

        dp[left][right] = n;
        int j = -1;
        for (int i = left; i < right; i++) {
            if (s.charAt(i) != s.charAt(right) && j == -1) {
                j = i;
            }

            if (j != -1) {
                dp[left][right] = Math.min(dp[left][right], 1 + solve(s, n, j, i) + solve(s, n, i + 1, right));
            }
        }

